WITH kept_keys AS (SELECT id, product_id FROM order_items INTERSECT ALL SELECT id, product_id FROM order_items WHERE product_id IN (3, 13, 39)), reconciled AS (SELECT s.* FROM order_items s INNER JOIN kept_keys k ON s.id = k.id AND s.product_id = k.product_id) SELECT s.id, s.product_id, s.quantity, s.unit_price, (SELECT MIN(s2.revenue) FROM store_sales s2 WHERE s2.product_id = s.product_id) AS min_store_sale_revenue FROM reconciled s ORDER BY quantity DESC;
